# Simple group effects (PTSD - Control) within each task on the response scale,
# averaged over sex and race (equal weights, matching the effect coding) at the
# mean age, with random intercepts at zero
extract_group_deltas &lt;- function(model, model_name) {
  if (model_name == "Sentiment") {
    # estimate_contrasts() works per rating category for the ordinal model, so
    # compare expected ratings, computed per posterior draw
    probs &lt;- estimate_means(model, by = c("task", "ptsd"), re_formula = NA, keep_iterations = TRUE) |&gt;
      as.data.frame()
    iters &lt;- grep("^iter_", names(probs), value = TRUE)
    out &lt;- probs |&gt;
      mutate(Response = as.numeric(as.character(Response))) |&gt;
      summarize(.by = c(task, ptsd), across(all_of(iters), \(p) sum(Response * p))) |&gt;
      pivot_longer(all_of(iters), names_to = "draw") |&gt;
      pivot_wider(names_from = ptsd, values_from = value) |&gt;
      mutate(diff = `1` - `0`) |&gt;
      summarize(
        .by = task,
        Estimate = median(diff),
        CI_Low = quantile(diff, 0.025),
        CI_High = quantile(diff, 0.975),
        pd = max(mean(diff &gt; 0), mean(diff &lt; 0))
      ) |&gt;
      transmute(Feature = model_name, Task = as.character(task), Estimate, CI_Low, CI_High, pd)
    return(out)
  }
  ec &lt;- estimate_contrasts(model, contrast = "ptsd", by = "task", re_formula = NA) |&gt;
    as.data.frame()
  stopifnot(all(ec$Level1 == "1" & ec$Level2 == "0"))  # PTSD minus Control
  ec |&gt;
    transmute(
      Feature = model_name,
      Task = as.character(task),
      Estimate = Median,
      CI_Low = CI_low,
      CI_High = CI_high,
      pd
    )
}

